import numpy as np, itertools
lines = open('opt2.xyz').read().split('\n')
n = int(lines[0]); els, xyz = [], []
for l in lines[2:2+n]:
    p = l.split(); els.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz = np.array(xyz)
def d(i,j): return np.linalg.norm(xyz[i]-xyz[j])
print("Os-Cl %.2f %.2f | Os=C1 %.2f Os-C2 %.2f | Os-P %.2f %.2f | C1-C3 %.2f C2-C3 %.2f"%(d(0,1),d(0,2),d(0,3),d(0,4),d(0,5),d(0,6),d(3,7),d(4,7)))
vecs = {i: xyz[i]-xyz[0] for i in (1,2,3,4,5,6)}
def ang(i,j):
    a,b = vecs[i],vecs[j]
    return round(np.degrees(np.arccos(a@b/np.linalg.norm(a)/np.linalg.norm(b))),1)
for i,j in itertools.combinations((1,2,3,4,5,6),2):
    print(i,j,ang(i,j), end='   ')
print()
